import json
# Check EDGAR for MENS and NBP tickers
import urllib.request
for ticker in ['MENS','NBP']:
    try:
        url = f'https://efts.sec.gov/LATEST/search-index?q=%22{ticker}%22&dateRange=custom&startdt=2024-01-01&enddt=2026-06-23&forms=10-K,20-F&hits.hits._source=period_of_report,file_date,entity_name,file_num'
        req = urllib.request.Request(url, headers={'User-Agent':'biotech-screener research@example.com'})
        data = json.loads(urllib.request.urlopen(req, timeout=10).read())
        hits = data.get('hits',{}).get('hits',[])
        if hits:
            for h in hits[:2]:
                src = h.get('_source',{})
                print(f'{ticker}: {src.get(\"entity_name\")} filed {src.get(\"file_date\")}')
        else:
            print(f'{ticker}: no hits')
    except Exception as e:
        print(f'{ticker}: error {e}')
